\mathsf{DerTree}_{STT}
=
\{(V,E,r,\ell):(V,E,r)\in\mathsf{FinRootTree}_{STT}
\land \ell:V\to\mathsf{Eq}_{STT}
\land
\forall v\in V\ \exists k_v\in\omega\ \exists e_v:k_v\to V\,
[
\operatorname{rng}(e_v)=\{w\in V:(v,w)\in E\}
\land
(((i\mapsto\ell(e_v(i)))_{i<k_v}),\ell(v))\in\mathsf{Rule}_{STT}
]\}.
